interface.definition:
if(
  ri!isInitialAmend,
  /*SAVE AND EXIT FOR INITIAL AMEND*/
  #"SYSTEM_SYSRULES_ButtonWidget"(
    label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155714",
    value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155714",
    showWhen: and(
      ri!isInitialAmend = true, 
      ri!isEdit = false
    ),
    saveInto: {
      ri!buttonValue,
      a!save(
        ri!rotationalAskDetails,
        ri!selectedBUs
      ),
      /*update RA versions by 1 in lines above, and update mod by, mod on, created on, created by*/
      #"SYSTEM_SYSRULES_forEach"(
        items: ri!rotationalAskDetails,
        expression: {
          a!save(
            fv!item.version,
            ri!newVersion
          ),
          a!save(
            {
              fv!item.modifiedBy,
              fv!item.createdBy
            },
            loggedInUser()
          ),
          a!save(
            {
              fv!item.createdOn,
              fv!item.modifiedOn
            },
            now()
          ),
          a!save(
            fv!item.askDetailId,
            null
          ),
          a!save(
            fv!item.iscompleted,
            false
          )
        }
      ),
      /*when we initially amend we need to create a new task row for the new amended version*/
      a!save(
        ri!task,
        'type!{urn:com:appian:types:CAW}CAW_Task'(
          requestId: ri!ask.askId,
          taskName: if(ri!region=#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11605098",
          /*ri!ask.fYear&" "&*/ri!ask.askName&" Rotational ASK - Amended",
          ri!ask.fYear&" "&ri!region&" Rotational ASK - Amended"),
          moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
          statusId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3165924",
          assigneeId: ri!loggedInUserId,
          isAssigneeGroup: false,
          isLocked: false,
          isTaskAmend: true,
          isCompleted: false,
          isApproved: false,
          version: ri!newVersion,
          createdBy: loggedInUser(),
          createdOn: now(),
          modifiedBy: loggedInUser(),
          modifiedOn: now()
        )
      ),
      /*when we initially amend we need to update the ask*/
      a!save(
        ri!ask.isCompleted,
        false
      ),
      a!save(
        ri!ask.version,
        ri!newVersion
      ),
      a!save(
        ri!ask.statusId,
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3165924",
      ),
      a!save(
        ri!ask.modifiedBy,
        loggedInUser()
      ),
      a!save(
        ri!ask.modifiedOn,
        now()
      ),
      /*only create and save a comment if there is one to write*/
      if(
        a!isNullOrEmpty(ri!comment.comment),
        {},
        a!save(
          ri!comment,
          'type!{urn:com:appian:types:CAW}CAW_Comment'(
            requestId: ri!ask.askId,
            moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
            comment: ri!comment.comment,
            isDraft: true,
            isActive: true,
            version: ri!newVersion,
            createdBy: loggedInUser(),
            createdOn: now(),
            modifiedBy: loggedInUser(),
            modifiedOn: now()
          )
        )
      ),
      /*audit history for the intial amended ASK as well as the save and exit on task*/
      a!save(
        ri!auditHistory,
        {
          /*We only want the amended ASK created audit the first time they save and exit*/
          if(
            a!isNullOrEmpty(ri!task.taskId),
            'type!{urn:com:appian:types:CAW}CAW_Audit'(
              taskId: ri!task.taskId,
              requestId: ri!ask.askId,
              version: ri!newVersion,
              moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
              statusId:  ri!task.statusId,
              action: "Rotational ASK Amended",
              description: "Rotational ASK V"&ri!newVersion&" created",
              createdBy: loggedInUser(),
              createdOn: now()
            ),
            null
          )
        }
      )
    },
    submit: true,
    style: "SECONDARY",
    confirmMessage: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3254608",
  ),
  #"SYSTEM_SYSRULES_ButtonWidget"(
    label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155714",
    value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155714",
    saveInto: {
      ri!buttonValue,
      a!save(
        ri!rotationalAskDetails,
        ri!selectedBUs
      ),
      if(
        ri!isEdit,
        {
          a!save(
            {
              ri!ask.modifiedBy,
              ri!task.modifiedBy
            },
            loggedInUser()
          ),
          a!save(
            {
              ri!ask.modifiedOn,
              ri!task.modifiedOn
            },
            now()
          )
        },
        {
          a!save(
            ri!ask,
            'type!{urn:com:appian:types:CAW}CAW_Ask'(
              fYear: ri!ask.fYear,
              regionId: ri!ask.regionId,
              typeId: ri!ask.typeId,
              askName: ri!ask.askName,
              statusId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3165924",
              isActive: true,
              isCompleted: false,
              version: 1,
              latestCompletedVersion: 0,
              createdBy: loggedInUser(),
              createdOn: now(),
              modifiedBy: loggedInUser(),
              modifiedOn: now()
            )
          ),
          a!save(
            ri!task,
            'type!{urn:com:appian:types:CAW}CAW_Task'(
              taskName: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3813977"(
                ask: ri!ask,
                region: ri!region
              ),
              moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
              statusId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3165924",
              assigneeId: ri!loggedInUserId,
              isAssigneeGroup: false,
              isLocked: false,
              isTaskAmend: false,
              isApproved: false,
              isCompleted: false,
              version: 1,
              createdBy: loggedInUser(),
              createdOn: now(),
              modifiedBy: loggedInUser(),
              modifiedOn: now()
            )
          )
        }
      ),
      /*COMMENT LOGIC*/
      if(
        and(
          a!isNullOrEmpty(ri!previousComment),
          a!isNotNullOrEmpty(ri!comment.comment)
        ),
        /*Create the whole comment CDT*/
        a!save(
          ri!comment,
          'type!{urn:com:appian:types:CAW}CAW_Comment'(
            commentId: ri!comment.commentId,
            requestId: if(
              isnull(ri!comment.requestId),
              ri!ask.askId,
              ri!comment.requestId
            ),
            moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
            comment: ri!comment.comment,
            isActive: true,
            isDraft: true,
            version: ri!task.version,
            createdBy: loggedInUser(),
            createdOn: now(),
            modifiedBy: loggedInUser(),
            modifiedOn: now()
          )
        ),
        if(
          and(
            a!isNotNullOrEmpty(ri!previousComment),
            a!isNullOrEmpty(ri!comment.comment)
          ),
          /*Clear the comment/Delete the row of data */
          a!save(
            ri!commentIDtoDelete,
            ri!comment.commentId
          ),
          if(
            ri!comment.comment <> ri!previousComment,
            {
              a!save(ri!comment.modifiedBy,loggedInUser()),
              a!save(ri!comment.modifiedOn,now())
            },
            {}
          )
        )
      ),
      /*audit history for the intial create ASK as well as the save and exit on task*/
      a!save(
        ri!auditHistory,
        {
          /*We only want the created ASK created audit the first time they save and exit*/
          if(
            isnull(ri!task.taskId),
            'type!{urn:com:appian:types:CAW}CAW_Audit'(
              requestId: ri!ask.askId,
              version: 1,
              moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164387",
              statusId:  ri!task.statusId,
              action: "Rotational ASK Created",
              description: "Rotational ASK V1 created",
              createdBy: loggedInUser(),
              createdOn: now()
            ),
            null
          )
        }
      )
    },
    submit: true,
    style: "SECONDARY",
    confirmMessage: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3254608",
    validate: true
  )
)
